INSERT INTO ride_types(code,name,capacity,service,display_order) VALUES ('standard','Standard',4,'ride',1),('comfort','Comfort',4,'ride',2),('premium','Premium',4,'ride',3),('xl','XL',6,'ride',4),('ev','EV',4,'ride',5);
INSERT INTO cities(slug,name,timezone,currency,active) VALUES ('yangon','Yangon','Asia/Yangon','MMK',true);
WITH c AS (SELECT id FROM cities WHERE slug='yangon'), v AS (
  INSERT INTO fare_versions(city_id,version,status,effective_from) SELECT id,1,'active',now() FROM c RETURNING id
)
INSERT INTO fare_plans(fare_version_id,ride_type_id,base_fare_mmk,included_distance_meters,per_km_mmk,low_speed_threshold_kph,low_speed_per_minute_mmk,minimum_fare_mmk,cash_rounding_unit_mmk,multiplier)
SELECT v.id,rt.id,5000,3000,1500,10,150,5000,100,CASE rt.code WHEN 'comfort' THEN 1.25 WHEN 'premium' THEN 1.7 WHEN 'xl' THEN 1.9 WHEN 'ev' THEN 1.05 ELSE 1 END FROM v CROSS JOIN ride_types rt;
